from pathlib import Pathfrom datetime import date, datetimeimport jsonimport mathimport sysfrom openpyxl import load_workbookfrom openpyxl.utils.datetime import from_excelSCRIPT_DIR = Path(__file__).resolve().parentEXCEL_FILE = SCRIPT_DIR.parent / 'Museum Radar Seed Dataset v1.xlsx'DATA_DIR = SCRIPT_DIR / 'data'EXHIBITIONS_JSON = DATA_DIR / 'exhibitions.json'WATCHLIST_JSON = DATA_DIR / 'watchlist.json'EXPECTED_FIELDS = [    'exhibition_id', 'exhibition_title', 'institution_name', 'city',    'state_region', 'exhibition_url', 'source_url', 'opening_date',    'closing_date', 'ticket_release_date', 'reservation_required',    'first_discovered_date', 'last_checked_date', 'last_changed_date',    'primary_category', 'secondary_tags', 'short_description',    'why_relevant', 'notable_content', 'distance_miles', 'trip_type',    'ticket_status', 'ticket_price', 'presale_member_info',    'user_status', 'personal_notes', 'is_new', 'change_type',    'archive_status',]DATE_FIELDS = {    'opening_date', 'closing_date', 'ticket_release_date',    'first_discovered_date', 'last_checked_date', 'last_changed_date',}PRIORITY_FIELDS = {    'priority_watchlist_status', 'priority_watchlist_id',    'priority_match_reason',}def convert_date(value, epoch):    if value is None or (isinstance(value, str) and not value.strip()):        return None    if isinstance(value, datetime):        return value.date().isoformat()    if isinstance(value, date):        return value.isoformat()    if isinstance(value, (int, float)) and not isinstance(value, bool):        if not math.isfinite(value):            raise ValueError('Invalid numeric date: {!r}'.format(value))        if 0 <= value < 1000:            return None        result = from_excel(value, epoch=epoch)        if isinstance(result, datetime):            return result.date().isoformat()        if isinstance(result, date):            return result.isoformat()        raise ValueError('Invalid Excel date: {!r}'.format(value))    if isinstance(value, str):        value = value.strip()        if value.isdigit():            return convert_date(int(value), epoch)        for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%m/%d/%y'):            try:                return datetime.strptime(value, fmt).date().isoformat()            except ValueError:                pass    raise ValueError('Invalid date value: {!r}'.format(value))def convert_boolean(value):    if value is None or value == '':        return False    if isinstance(value, bool):        return value    text = str(value).strip().lower()    if text in ('true', 'yes', 'y', '1'):        return True    if text in ('false', 'no', 'n', '0'):        return False    raise ValueError('Invalid boolean value: {!r}'.format(value))def convert_distance(value):    if value is None or value == '':        return None    try:        number = float(value)        if not math.isfinite(number):            raise ValueError()        return int(number) if number.is_integer() else number    except (ValueError, TypeError):        raise ValueError('Invalid distance_miles: {!r}'.format(value))def convert_value(field, value, epoch):    if field in DATE_FIELDS:        return convert_date(value, epoch)    if field == 'secondary_tags':        return [x.strip() for x in str(value).split(';') if x.strip()] if value is not None else []    if field == 'distance_miles':        return convert_distance(value)    if field == 'is_new':        return convert_boolean(value)    if isinstance(value, (datetime, date)):        return value.isoformat()    if isinstance(value, str):        return value.strip() or None    return valuedef headers_for(sheet):    return [str(c.value).strip() if c.value is not None else '' for c in sheet[1]]def read_records(sheet, key_field, required_fields, epoch, fields=None):    headers = headers_for(sheet)    if len([h for h in headers if h]) != len(set(h for h in headers if h)):        raise RuntimeError('Duplicate headers in sheet {}'.format(sheet.title))    column_map = {h: i for i, h in enumerate(headers) if h}    missing = set(required_fields) - set(column_map)    if missing:        raise RuntimeError('Missing columns in {}: {}'.format(sheet.title, ', '.join(sorted(missing))))    if fields is None:        fields = [h for h in headers if h]    missing = set(fields) - set(column_map)    if missing:        raise RuntimeError('Missing columns in {}: {}'.format(sheet.title, ', '.join(sorted(missing))))    records = []    seen = set()    errors = []    for row_number, row in enumerate(sheet.iter_rows(min_row=2, values_only=True), 2):        raw_id = row[column_map[key_field]]        if raw_id is None or not str(raw_id).strip():            continue        try:            record = {}            for field in fields:                idx = column_map[field]                raw = row[idx] if idx < len(row) else None                record[field] = convert_value(field, raw, epoch)            record_id = str(record[key_field]).strip()            record[key_field] = record_id            if record_id in seen:                raise ValueError('Duplicate {}: {}'.format(key_field, record_id))            seen.add(record_id)            for field in required_fields:                if not record.get(field):                    raise ValueError('Missing {}'.format(field))            records.append(record)        except Exception as exc:            errors.append('Row {}: {}'.format(row_number, exc))    if errors:        raise RuntimeError('Validation errors in {}:\n{}'.format(sheet.title, '\n'.join('  - ' + e for e in errors)))    return recordsdef load_data():    if not EXCEL_FILE.exists():        raise FileNotFoundError('Workbook not found: {}'.format(EXCEL_FILE))    workbook = load_workbook(EXCEL_FILE, data_only=True, read_only=True)    try:        exhibition_sheet = next((s for s in workbook.worksheets if 'exhibition_id' in headers_for(s)), None)        if exhibition_sheet is None:            raise RuntimeError('No worksheet has an exhibition_id header')        fields = EXPECTED_FIELDS + [f for f in ('priority_watchlist_status', 'priority_watchlist_id', 'priority_match_reason') if f in headers_for(exhibition_sheet)]        exhibitions = read_records(exhibition_sheet, 'exhibition_id', ('exhibition_id', 'exhibition_title', 'institution_name'), workbook.epoch, fields)        watchlist = None        if 'Priority Watchlist' in workbook.sheetnames:            watchlist = read_records(workbook['Priority Watchlist'], 'watch_id', ('watch_id',), workbook.epoch)        return exhibitions, watchlist    finally:        workbook.close()def write_temp(path, payload):    path.parent.mkdir(parents=True, exist_ok=True)    tmp = path.with_suffix(path.suffix + '.tmp')    with tmp.open('w', encoding='utf-8') as output:        json.dump(payload, output, indent=2, ensure_ascii=False, allow_nan=False)    return tmpdef main():    print('Museum Radar updater')    print('Reading:', EXCEL_FILE)    exhibitions, watchlist = load_data()    exhibit_payload = {        'schema_version': '1.0',        'source': EXCEL_FILE.name,        'record_count': len(exhibitions),        'exhibitions': exhibitions,    }    pending = [(write_temp(EXHIBITIONS_JSON, exhibit_payload), EXHIBITIONS_JSON)]    if watchlist is not None:        watch_payload = {            'schema_version': '1.0',            'source': EXCEL_FILE.name,            'record_count': len(watchlist),            'watchlist': watchlist,        }        pending.append((write_temp(WATCHLIST_JSON, watch_payload), WATCHLIST_JSON))    for tmp, dest in pending:        tmp.replace(dest)    print('Exhibitions:', len(exhibitions))    if watchlist is not None:        print('Watchlist entries:', len(watchlist))    print('Validation errors: 0')    for _, dest in pending:        print('Updated:', dest)if __name__ == '__main__':    try:        main()    except Exception as exc:        print('UPDATE STOPPED')        print(exc)        sys.exit(1)